// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(recipient != address(c));
        bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);
        vm.prank(nonOwner);
        bool reverted = false;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }
}
